from pathlib import Path
import json,subprocess,statistics,fcntl,hashlib
p=Path(__file__).parent;vs=['baseline','count_index','radix11','radix10'];res={'status':'INCOMPLETE','builds':[],'cases':{},'sources':{n:hashlib.sha256((p/(n+'.hpp')).read_bytes()).hexdigest()for n in vs}}
for mode,cc in {'zen':['/usr/bin/g++','-march=znver2'],'native':['/usr/bin/g++','-march=native'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}.items():
 for v in vs:
  cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(p/(v+'.hpp'))+'"',str(p/'bench.cpp'),'-o',str(p/(mode+'_'+v))];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,(cmd,q.stderr);res['builds'].append(cmd)
 print('compiled',mode,flush=True)
with open('/tmp/sirkit_performance_cpu16.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for mode in ['zen','native','clang']:
  res['cases'][mode]={}
  cases=[(2,10000,0,'normal'),(32,2000,0,'normal'),(4096,8,0,'normal'),*[(131072,1,s,'normal')for s in [0,1,2,3,4,5,6,7,8]],(4096,8,0,'sorted'),(131072,1,0,'sorted'),(150001,1,0,'normal'),(150001,1,3,'normal'),(500000,1,0,'normal'),(500000,1,3,'normal'),(500000,1,7,'normal')]
  for n,loops,shape,api in cases:
   raw={v:[]for v in vs};checksum=None
   for rep in range(5):
    for v in vs[rep%4:]+vs[:rep%4]:
     out=subprocess.check_output(['taskset','-c','16',str(p/(mode+'_'+v)),str(n),str(loops),str(shape),api]).decode().split();raw[v].append(float(out[0]));checksum=out[1]if checksum is None else checksum;assert checksum==out[1],(mode,n,shape,v,out,checksum)
   med={v:statistics.median(x)for v,x in raw.items()};rat={v:x/med['baseline']for v,x in med.items()};res['cases'][mode][f'{n}/{shape}/{api}']={'raw':raw,'medians':med,'ratios':rat,'loops':loops};print(mode,n,shape,api,{k:round(v,3)for k,v in rat.items()},flush=True)
res['status']='PASS';(p/'results.json').write_text(json.dumps(res,indent=2)+'\n')

